class Permissions:
    def __init__(self):
        self.roles_permissions = {
            'viewer': ['read'],
            'editor': ['read', 'write']
        }

    def allowed(self, role, action):
        if role not in self.roles_permissions:
            return False  # Unknown roles are denied
        if action in self.roles_permissions[role]:
            return True
        return False

    def roles_for(self, action):
        roles = []
        for role, permissions in self.roles_permissions.items():
            if action in permissions:
                roles.append(role)
        return sorted(roles)
