class PriceEngine:
    def __init__(self):
        self.pricing_strategy = {
            'basic': lambda amount: round(amount, 2),
            'pro': lambda amount: round(amount * 0.9, 2)
        }

    def price(self, plan, amount):
        if plan not in self.pricing_strategy:
            raise KeyError(f"Unknown plan: {plan}")
        return self.pricing_strategy[plan](amount)

    def remove_plan(self, plan):
        if plan not in self.pricing_strategy:
            raise KeyError(f"Unknown plan: {plan}")
        discount_fraction = 1.0 if plan == 'basic' else 0.1
        del self.pricing_strategy[plan]
        return discount_fraction

