class PriceEngine:
    DISCOUNT_PRO = 0.90

    @staticmethod
    def price(plan, amount):
        """
        Calculates the price based on the plan type.

        :param plan: str, the plan type ('basic' or 'pro')
        :param amount: float, the original amount before discount
        :return: float, the final price rounded to 2 decimal places
        :raises KeyError: if the plan is not recognized
        """
        if plan == 'basic':
            return round(amount, 2)
        elif plan == 'pro':
            discounted_amount = amount * PriceEngine.DISCOUNT_PRO
            return round(discounted_amount, 2)
        else:
            raise KeyError(f"Unknown plan: {plan}")

    @staticmethod
    def remove_plan(plan):
        """
        Removes a plan and returns its discount fraction.

        :param plan: str, the plan type to remove ('basic' or 'pro')
        :return: float, the discount fraction that was removed
        :raises KeyError: if the plan is not recognized
        """
        if plan == 'basic':
            # Basic plan has no discount, so discount fraction is 1.0
            return 1.0
        elif plan == 'pro':
            # Remove the pro discount
            discount = PriceEngine.DISCOUNT_PRO
            # Note: In a real implementation, we would need to modify class state
            # For this simple case, we just return the discount fraction
            return discount
        else:
            raise KeyError(f"Unknown plan: {plan}")
