class Router:
    def __init__(self):
        self.routes = {
            '/': 'home',
            '/health': 'ok'
        }

    def resolve(self, path):
        return self.routes.get(path)

    def rename(self, old_path, new_path):
        if old_path not in self.routes:
            return None

        target = self.routes.pop(old_path)
        self.routes[new_path] = target
        return target
